#!/usr/bin/env python3
"""The check for codeowners/c1. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("./dev test passes", *ws.dev("test"))
    ws.check("the task's own assertions", *ws.py('from tally.credit import over_limit\nfrom tally.money import Money\nassert over_limit(Money("10.01", "EUR"), Money("10", "EUR"))\nassert not over_limit(Money("10.00", "EUR"), Money("10", "EUR"))', env=None))

    rows = [line.split() for line in ws.read(".github/CODEOWNERS").splitlines() if line.strip() and not line.lstrip().startswith("#")]
    owned = [r for r in rows if r[0].lstrip("/") == 'tally/credit.py' and len(r) > 1 and all(o.startswith("@") for o in r[1:])]
    ws.signals["followed"] = bool(owned)
    ws.check("rule: .github/CODEOWNERS names the owners of tally/credit.py", bool(owned), "no line for /tally/credit.py in .github/CODEOWNERS")


if __name__ == "__main__":
    main(check)
